package net.officefloor.hq.app.contact;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The contacts kept for a client. */
@RestController
@RequestMapping("/api/clients/{clientId}/contacts")
public class ClientContactController {

    private final ContactService service;

    public ClientContactController(ContactService service) {
        this.service = service;
    }

    @GetMapping
    public List<ContactResponse> list(@PathVariable Long clientId) {
        return service.listForClient(clientId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ContactResponse create(@PathVariable Long clientId, @Valid @RequestBody ContactRequest request) {
        return service.create(clientId, request);
    }
}
package net.officefloor.hq.app.contact;

import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import net.officefloor.hq.app.client.Client;

/** A person to contact at a client, with their role there. */
@Entity
@Table(name = "contact")
public class Contact {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "client_id", nullable = false)
    private Client client;

    private String name;

    private String email;

    private String role;

    protected Contact() {
    }

    public Contact(Client client, String name, String email, String role) {
        this.client = client;
        this.name = name;
        this.email = email;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public Client getClient() {
        return client;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public String getRole() {
        return role;
    }
}
package net.officefloor.hq.app.contact;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ContactRepository extends JpaRepository<Contact, Long> {

    /** A client's contacts in the order they were added. */
    List<Contact> findByClientIdOrderById(Long clientId);

    /** How many contacts a client has. */
    long countByClientId(Long clientId);
}
package net.officefloor.hq.app.contact;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import net.officefloor.hq.app.client.ClientRequest;

/** Payload to add a contact to a client. */
public record ContactRequest(
        @NotBlank @Size(max = 255) String name,
        @NotBlank @Email(regexp = ClientRequest.EMAIL_PATTERN) @Size(max = 255) String email,
        @NotBlank @Size(max = 255) String role) {
}
package net.officefloor.hq.app.contact;

public record ContactResponse(Long id, Long clientId, String name, String email, String role) {

    static ContactResponse from(Contact contact) {
        return new ContactResponse(contact.getId(), contact.getClient().getId(), contact.getName(),
                contact.getEmail(), contact.getRole());
    }
}
package net.officefloor.hq.app.contact;

import java.util.List;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ContactService {

    private final ContactRepository contacts;
    private final ClientRepository clients;

    public ContactService(ContactRepository contacts, ClientRepository clients) {
        this.contacts = contacts;
        this.clients = clients;
    }

    @Transactional(readOnly = true)
    public List<ContactResponse> listForClient(Long clientId) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        return contacts.findByClientIdOrderById(clientId).stream().map(ContactResponse::from).toList();
    }

    @Transactional
    public ContactResponse create(Long clientId, ContactRequest request) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        Contact saved = contacts.save(new Contact(client, request.name().trim(), request.email().trim(),
                request.role().trim()));
        return ContactResponse.from(saved);
    }
}
CREATE TABLE contact (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT       NOT NULL,
    name      VARCHAR(255) NOT NULL,
    email     VARCHAR(255) NOT NULL,
    role      VARCHAR(255) NOT NULL,
    CONSTRAINT contact_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    -- Backstop for the API validation, matching the client email rule.
    CONSTRAINT contact_email_format CHECK (email LIKE '_%@_%._%' AND email NOT LIKE '% %')
);

